import type { APIRequestContext } from "@playwright/test";
import { expect, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

const cases = [
  { file: "an empty file", name: "empty.txt", mimeType: "text/plain", buffer: Buffer.alloc(0), kind: "w9", status: 422, code: "empty_file" },
  { file: "a file of exactly 10 MiB + 1", name: "big.txt", mimeType: "text/plain", buffer: Buffer.alloc(TEN_MIB + 1, "x"), kind: "w9", status: 413, code: "file_too_large" },
  { file: "a \".exe\" file", name: "tool.exe", mimeType: "application/octet-stream", buffer: Buffer.from("MZ"), kind: "w9", status: 415, code: "unsupported_type" },
  { file: "a valid text file", name: "notes.txt", mimeType: "text/plain", buffer: Buffer.from("valid text"), kind: "passport", status: 422, code: "validation_error" },
];

async function createDraftVendor(member: APIRequestContext): Promise<string> {
  const res = await member.post("/api/vendors", {
    data: { name: uniqueName("Doc Vendor"), category: "services", contact_email: "ops@docvendor-northwind.com" },
  });
  expect(res.status(), await res.text()).toBe(201);
  return ((await res.json()) as { id: string }).id;
}

test.describe("upload vendor documents", () => {
  for (const c of cases) {
    test(`rejects ${c.file} as kind "${c.kind}" with ${c.code}`, { tag: "@DOC-04" }, async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const vendorId = await createDraftVendor(member);

      // Act
      const res = await member.post(`/api/vendors/${vendorId}/documents`, {
        multipart: {
          kind: c.kind,
          file: { name: c.name, mimeType: c.mimeType, buffer: c.buffer },
        },
      });

      // Assert
      const body = await res.text();
      expect(res.status(), body).toBe(c.status);
      expect((JSON.parse(body) as { error?: { code?: string } }).error?.code, body).toBe(c.code);
    });
  }
});
